import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('RATES object exists', () => {
  assert.equal(typeof RATES, 'object');
});

test('RATES has EUR', () => {
  assert.equal(RATES.EUR, 1);
});

test('RATES has USD', () => {
  assert.equal(RATES.USD, 1.085);
});

test('RATES has GBP', () => {
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to USD', () => {
  const result = convert(100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'number');
});

test('convert EUR to GBP', () => {
  const result = convert(100, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'number');
});

test('convert EUR to EUR', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 100);
});

test('convert with invalid currency returns error', () => {
  const result = convert(100, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert uses correct exchange rate', () => {
  const eurCents = 10000;
  const result = convert(eurCents, 'USD');
  assert.equal(result.ok, true);
  const expected = roundCents(eurCents * RATES.USD);
  assert.equal(result.value, expected);
});

test('convert rounds correctly', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'number');
  assert.equal(Number.isInteger(result.value), true);
});

test('convert with zero amount', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert with negative amount', () => {
  const result = convert(-100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value < 0, true);
});

test('convert large amount to USD', () => {
  const result = convert(1000000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1085000);
});

test('convert EUR to GBP calculation', () => {
  const eurCents = 10000;
  const result = convert(eurCents, 'GBP');
  assert.equal(result.ok, true);
  const expected = roundCents(eurCents * 0.8425);
  assert.equal(result.value, expected);
});

test('formatMoney EUR', () => {
  const result = formatMoney(123456, 'EUR');
  assert.equal(result, '€1,234.56');
});

test('formatMoney USD', () => {
  const result = formatMoney(123456, 'USD');
  assert.equal(result, '$1,234.56');
});

test('formatMoney GBP', () => {
  const result = formatMoney(123456, 'GBP');
  assert.equal(result, '£1,234.56');
});

test('formatMoney with zero amount', () => {
  const result = formatMoney(0, 'USD');
  assert.equal(result, '$0.00');
});

test('formatMoney with single cent', () => {
  const result = formatMoney(1, 'USD');
  assert.equal(result, '$0.01');
});

test('formatMoney with no thousands', () => {
  const result = formatMoney(999, 'USD');
  assert.equal(result, '$9.99');
});

test('formatMoney with thousands', () => {
  const result = formatMoney(1000000, 'USD');
  assert.equal(result, '$10,000.00');
});

test('formatMoney with millions', () => {
  const result = formatMoney(123456789, 'USD');
  assert.equal(result, '$1,234,567.89');
});

test('formatMoney with negative amount', () => {
  const result = formatMoney(-123456, 'USD');
  assert.equal(result, '-$1,234.56');
});

test('formatMoney negative EUR', () => {
  const result = formatMoney(-100, 'EUR');
  assert.equal(result, '-€1.00');
});

test('formatMoney negative GBP', () => {
  const result = formatMoney(-5000, 'GBP');
  assert.equal(result, '-£50.00');
});

test('formatMoney with unknown currency', () => {
  const result = formatMoney(123456, 'JPY');
  assert.equal(typeof result, 'string');
  assert.equal(result.length > 0, true);
});

test('formatMoney format consistency', () => {
  const amount = 987654;
  const eurResult = formatMoney(amount, 'EUR');
  const usdResult = formatMoney(amount, 'USD');
  const gbpResult = formatMoney(amount, 'GBP');
  assert.equal(eurResult, '€9,876.54');
  assert.equal(usdResult, '$9,876.54');
  assert.equal(gbpResult, '£9,876.54');
});

test('convert and formatMoney roundtrip', () => {
  const originalEur = 10000;
  const converted = convert(originalEur, 'USD');
  assert.equal(converted.ok, true);
  const formatted = formatMoney(converted.value, 'USD');
  assert.equal(typeof formatted, 'string');
  assert.equal(formatted.includes('$'), true);
});

test('convert multiple currencies', () => {
  const eurCents = 50000;
  const usd = convert(eurCents, 'USD');
  const gbp = convert(eurCents, 'GBP');
  const eur = convert(eurCents, 'EUR');
  assert.equal(usd.ok, true);
  assert.equal(gbp.ok, true);
  assert.equal(eur.ok, true);
  assert.equal(eur.value, eurCents);
  assert.equal(usd.value > eurCents, true);
  assert.equal(gbp.value < eurCents, true);
});

test('formatMoney uses comma thousands separator', () => {
  const result = formatMoney(1234567, 'USD');
  assert.equal(result.includes(','), true);
});

test('formatMoney two decimal places', () => {
  const result = formatMoney(123, 'USD');
  assert.equal(result, '$1.23');
});

test('formatMoney exact dollar amount', () => {
  const result = formatMoney(10000, 'USD');
  assert.equal(result, '$100.00');
});

test('convert preserves integer type', () => {
  const result = convert(12345, 'USD');
  assert.equal(Number.isInteger(result.value), true);
});

test('RATES are numbers', () => {
  assert.equal(typeof RATES.EUR, 'number');
  assert.equal(typeof RATES.USD, 'number');
  assert.equal(typeof RATES.GBP, 'number');
});

test('convert USD bigger than EUR', () => {
  const result = convert(100, 'USD');
  const expected = roundCents(100 * 1.085);
  assert.equal(result.value, expected);
  assert.equal(result.value > 100, true);
});

test('convert GBP smaller than EUR', () => {
  const result = convert(100, 'GBP');
  const expected = roundCents(100 * 0.8425);
  assert.equal(result.value, expected);
  assert.equal(result.value < 100, true);
});

test('formatMoney all currencies same format structure', () => {
  const amount = 54321;
  const eur = formatMoney(amount, 'EUR');
  const usd = formatMoney(amount, 'USD');
  const gbp = formatMoney(amount, 'GBP');
  assert.equal(eur.includes('.'), true);
  assert.equal(usd.includes('.'), true);
  assert.equal(gbp.includes('.'), true);
});

test('convert case sensitive currency', () => {
  const result = convert(100, 'usd');
  assert.equal(result.ok, false);
});
TESTEOF
